    // We also need to remember if --keyed was set (for the conflict display).
    let mut keyed_set = false;
    let mut derive_set = false;
    let mut check_set = false;
    let mut tag_set = false;
    let mut no_names_set = false;
    let mut raw_set = false;
    let mut length_set = false;

    // The "primary option" that shows up in the Usage line for conflict errors.
    // When there's a conflict, clap shows "Usage: executable <primary_option> <FILE>..."
    // The primary option is the one parsed first (or the one the conflict was detected against).
    // We'll track the last-seen "exclusive" option to use in Usage lines for subsequent errors.
    // A simpler approach: record the argument-specific usage string based on what was set.
    fn usage_for_primary(kw: &str) -> String {
        match kw {
            "--keyed" => "executable --keyed <FILE>...".to_string(),
            "--derive-key" => "executable --derive-key <CONTEXT> <FILE>...".to_string(),
            "--length" => "executable --length <LEN> <FILE>...".to_string(),
            "--no-names" => "executable --no-names <FILE>...".to_string(),
            "--raw" => "executable --raw <FILE>...".to_string(),
            "--tag" => "executable --tag <FILE>...".to_string(),
            "--check" => "executable --check <FILE>...".to_string(),
            "--quiet" => "executable --check --quiet <FILE>...".to_string(),
            _ => "executable [OPTIONS] [FILE]...".to_string(),
        }
    }

    fn conflict(primary: &str, primary_disp: &str, other_disp: &str) -> ! {
        let usage = usage_for_primary(primary);
        let msg = format!("the argument '{}' cannot be used with '{}'", other_disp, primary_disp);
        arg_error(&msg, &usage);
    }

    // Helper to display an option name with its metavar
    fn disp(name: &str) -> &'static str {
        match name {
            "--keyed" => "--keyed",
            "--derive-key" => "--derive-key <CONTEXT>",
            "--length" | "-l" => "--length <LEN>",
            "--seek" => "--seek <SEEK>",
            "--num-threads" => "--num-threads <NUM>",
            "--no-mmap" => "--no-mmap",
            "--no-names" => "--no-names",
            "--raw" => "--raw",
            "--tag" => "--tag",
            "--check" | "-c" => "--check",
            "--quiet" => "--quiet",
            _ => "",
        }
    }

