fn write_hex(out: &mut impl Write, bytes: &[u8]) -> io::Result<()> {
    for b in bytes {
        write!(out, "{:02x}", b)?;
    }
    Ok(())
}

// Path name escaping rules (GNU coreutils style).
// Returns (is_escaped, escaped_string).
fn maybe_escape_filename(path: &Path) -> (bool, String) {
    // Convert path to bytes; for non-UTF-8 we'll use lossy conversion similar to Rust's display.
    // For this implementation we treat it as an OsStr-to-bytes conversion via lossy.
    let s = path.to_string_lossy();
    let needs_escape = s.contains('\\') || s.contains('\n') || s.contains('\r');
    if !needs_escape {
        return (false, s.into_owned());
    }
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            _ => out.push(c),
        }
    }
    (true, out)
}

fn unescape_filename(s: &str) -> Option<String> {
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next()? {
                '\\' => out.push('\\'),
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                _ => return None,
            }
        } else {
            out.push(c);
        }
    }
    Some(out)
}

fn format_hash_line(hash_hex: &str, path: &Path, tag: bool, no_names: bool) -> String {
    if no_names {
        return format!("{}\n", hash_hex);
    }
    let (escaped, name) = maybe_escape_filename(path);
    let prefix = if escaped { "\\" } else { "" };
    if tag {
        format!("{}BLAKE3 ({}) = {}\n", prefix, name, hash_hex)
    } else {
        format!("{}{}  {}\n", prefix, hash_hex, name)
    }
}

// Read a file or stdin into a byte vector via Hasher::update
fn hash_reader<R: Read>(hasher: &mut blake3::Hasher, reader: R) -> io::Result<()> {
    let mut br = BufReader::with_capacity(1 << 16, reader);
    loop {
        let buf = br.fill_buf()?;
        if buf.is_empty() {
            return Ok(());
        }
        let len = buf.len();
        hasher.update(buf);
        br.consume(len);
    }
}

fn hash_path(path: &Path, key: &HashKey) -> io::Result<Vec<u8>> {
    let mut hasher = key.new_hasher();
    if path == Path::new("-") {
        let stdin = io::stdin();
        hash_reader(&mut hasher, stdin.lock())?;
    } else {
        let file = File::open(path)?;
        hash_reader(&mut hasher, file)?;
    }
    // We can't pass the length here; let caller handle output size and seek.
    // Instead, we return the full incremental state externally — but we cannot clone Hasher easily.
    // Wrap differently: produce a fixed-size output only after caller tells us the length/seek.
    // To keep it simple, return a special marker Vec — but we need to allow XOF.
    // We'll change the API: let the caller finalise. But we need access to Hasher after.
    // Let's instead return a serialised Hasher... actually just finalise here with a sentinel;
    // simpler: separate function that returns Vec with desired length/seek.
    let _ = hasher;
    unreachable!()
}

// A wrapper around the various hasher-construction modes.
enum HashKey {
    Regular,
    Keyed([u8; 32]),
    DeriveKey(String),
}

impl HashKey {
    fn new_hasher(&self) -> blake3::Hasher {
        match self {
            HashKey::Regular => blake3::Hasher::new(),
            HashKey::Keyed(k) => blake3::Hasher::new_keyed(k),
            HashKey::DeriveKey(c) => blake3::Hasher::new_derive_key(c),
        }
    }
}

fn hash_file_like<R: Read>(
    reader: R,
    key: &HashKey,
    length: u64,
    seek: u64,
) -> io::Result<Vec<u8>> {
    let mut hasher = key.new_hasher();
    hash_reader(&mut hasher, reader)?;
    let mut out = vec![0u8; length as usize];
    hasher.finalize_seek(seek, &mut out);
    Ok(out)
}

fn hash_file(path: &Path, key: &HashKey, length: u64, seek: u64) -> io::Result<Vec<u8>> {
    if path == Path::new("-") {
        let stdin = io::stdin();
        hash_file_like(stdin.lock(), key, length, seek)
    } else {
        let file = File::open(path)?;
        hash_file_like(file, key, length, seek)
    }
}

fn to_hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

fn do_hash(args: &Args, key: &HashKey) -> ExitCode {
    let mut any_error = false;

    // Decide list of inputs.
    let inputs: Vec<PathBuf> = if args.files.is_empty() {
        if args.keyed {
            // Already validated, but just in case.
            return ExitCode::from(2);
        }
        vec![PathBuf::from("-")]
    } else {
        args.files.clone()
    };

    if args.raw && inputs.len() > 1 {
        let mut stderr = io::stderr().lock();
        let _ = writeln!(stderr, "Error: Only one filename can be provided when using --raw");
        return ExitCode::from(1);
    }

    for path in &inputs {
        // For --keyed, '-' is not allowed as an input file (stdin used for key).
        if args.keyed && path == Path::new("-") {
            let mut stderr = io::stderr().lock();
            let _ = writeln!(stderr, "b3sum: -: Cannot open `-` in keyed mode");
            any_error = true;
            continue;
        }
        match hash_file(path, key, args.length, args.seek) {
            Ok(bytes) => {
                if args.raw {
                    let mut stdout = io::stdout().lock();
                    if let Err(e) = stdout.write_all(&bytes) {
                        let mut stderr = io::stderr().lock();
                        let _ = writeln!(stderr, "b3sum: {}", e);
                        any_error = true;
                    }
                } else {
                    let hex = to_hex(&bytes);
                    let line = format_hash_line(&hex, path, args.tag, args.no_names);
                    let mut stdout = io::stdout().lock();
                    let _ = stdout.write_all(line.as_bytes());
                }
            }
            Err(e) => {
                let mut stderr = io::stderr().lock();
                let disp = path.display();
                let _ = writeln!(stderr, "b3sum: {}: {}", disp, e);
                any_error = true;
            }
        }
    }

    if any_error { ExitCode::from(1) } else { ExitCode::from(0) }
}

fn do_check(args: &Args, key: &HashKey) -> ExitCode {
    let mut any_error = false;
    let mut failed_count: u64 = 0;

    let inputs: Vec<PathBuf> = if args.files.is_empty() {
        vec![PathBuf::from("-")]
    } else {
        args.files.clone()
    };

    for input in &inputs {
        let reader: Box<dyn Read> = if input == Path::new("-") {
            Box::new(io::stdin().lock())
        } else {
            match File::open(input) {
                Ok(f) => Box::new(f),
                Err(e) => {
                    let mut stderr = io::stderr().lock();
                    let _ = writeln!(stderr, "Error: {}", e);
                    return ExitCode::from(1);
                }
            }
        };

        let br = BufReader::new(reader);
        for line_res in br.lines() {
            let line = match line_res {
                Ok(l) => l,
                Err(e) => {
                    let mut stderr = io::stderr().lock();
                    let _ = writeln!(stderr, "Error: {}", e);
                    return ExitCode::from(1);
                }
            };
            // Trim \r at end if present (for CRLF lines).
            let line = line.trim_end_matches('\r');
            // Parse the check line.
            match parse_check_line(line) {
                Ok((expected_hex, filename_escaped, is_escaped)) => {
                    // Decode the filename.
                    let filename = if is_escaped {
                        match unescape_filename(&filename_escaped) {
                            Some(s) => s,
                            None => {
                                let mut stderr = io::stderr().lock();
                                let _ = writeln!(stderr, "b3sum: Invalid escape sequence");
                                failed_count += 1;
                                any_error = true;
                                continue;
                            }
                        }
                    } else {
                        filename_escaped.clone()
                    };
                    // Prefixed name as it should be printed.
                    let display_name = if is_escaped {
                        format!("\\{}", filename_escaped)
                    } else {
                        filename_escaped.clone()
                    };

                    // Decode expected hex (must be 64 chars).
                    if expected_hex.len() != 64 {
                        let mut stderr = io::stderr().lock();
                        let _ = writeln!(stderr, "b3sum: Invalid hash length");
                        failed_count += 1;
                        any_error = true;
                        continue;
                    }
                    let expected = match hex_decode(&expected_hex) {
                        Some(b) => b,
                        None => {
                            let mut stderr = io::stderr().lock();
                            let _ = writeln!(stderr, "b3sum: Invalid hex");
                            failed_count += 1;
                            any_error = true;
                            continue;
                        }
                    };

                    // Compute the hash of the file.
                    let path = PathBuf::from(&filename);
                    match hash_file(&path, key, 32, 0) {
                        Ok(computed) => {
                            let matches = constant_time_eq(&computed, &expected);
                            let mut stdout = io::stdout().lock();
                            if matches {
                                if !args.quiet {
                                    let _ = writeln!(stdout, "{}: OK", display_name);
                                }
                            } else {
                                let _ = writeln!(stdout, "{}: FAILED", display_name);
                                failed_count += 1;
                                any_error = true;
                            }
                        }
                        Err(e) => {
                            let mut stdout = io::stdout().lock();
                            let _ = writeln!(stdout, "{}: FAILED ({})", display_name, e);
                            failed_count += 1;
                            any_error = true;
                        }
                    }
                }
                Err(err_kind) => {
                    let mut stderr = io::stderr().lock();
                    let _ = writeln!(stderr, "b3sum: {}", err_kind);
                    failed_count += 1;
                    any_error = true;
                }
            }
        }
    }

    if failed_count > 0 {
        let mut stderr = io::stderr().lock();
        let noun = if failed_count == 1 { "checksum" } else { "checksums" };
        let _ = writeln!(stderr, "b3sum: WARNING: {} computed {} did NOT match", failed_count, noun);
    }

    if any_error { ExitCode::from(1) } else { ExitCode::from(0) }
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() { return false; }
    let mut diff: u8 = 0;
    for i in 0..a.len() {
        diff |= a[i] ^ b[i];
    }
    diff == 0
}

fn hex_decode(s: &str) -> Option<Vec<u8>> {
    if s.len() % 2 != 0 { return None; }
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(s.len() / 2);
    let mut i = 0;
    while i < bytes.len() {
        let hi = hex_val(bytes[i])?;
        let lo = hex_val(bytes[i + 1])?;
        out.push((hi << 4) | lo);
        i += 2;
    }
    Some(out)
}

fn hex_val(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

// Parse a line from a checksum file; returns (hex, filename, is_escaped).
fn parse_check_line(line: &str) -> Result<(String, String, bool), &'static str> {
    if line.is_empty() {
        return Err("Empty line");
    }
    // Detect escape prefix '\'.
    let (is_escaped, rest) = if let Some(stripped) = line.strip_prefix('\\') {
        (true, stripped)
    } else {
        (false, line)
    };
    // BSD-style: "BLAKE3 (FILENAME) = HASH".
    if rest.starts_with("BLAKE3 (") {
        // Find the " = " after the closing paren.
        // Find the last ") = " to handle filenames that contain ')'.
        if let Some(idx) = rest.rfind(") = ") {
            let fname = &rest[8..idx];
            let hash = &rest[idx + 4..];
            // Validate hash length before anything else: require 64 hex chars.
            return Ok((hash.to_string(), fname.to_string(), is_escaped));
        } else {
            return Err("Invalid check line format");
        }
    }
    // Regular format: "HASH  FILENAME" (two spaces separator).
    if let Some(sep_idx) = rest.find("  ") {
        let hash = &rest[..sep_idx];
        let fname = &rest[sep_idx + 2..];
        return Ok((hash.to_string(), fname.to_string(), is_escaped));
    }
    Err("Invalid check line format")
}

fn main() -> ExitCode {
    let args = parse_args();

    // Build the key from --keyed or --derive-key.
    let key = if args.keyed {
        let mut buf = [0u8; 32];
        let mut n_read = 0;
        let stdin = io::stdin();
        let mut lock = stdin.lock();
        let mut small = [0u8; 64];
        loop {
            match lock.read(&mut small) {
                Ok(0) => break,
                Ok(n) => {
                    if n_read + n > 32 {
                        let mut stderr = io::stderr().lock();
                        let _ = writeln!(stderr, "Error: read more than 32 key bytes from stdin");
                        return ExitCode::from(1);
                    }
                    buf[n_read..n_read + n].copy_from_slice(&small[..n]);
                    n_read += n;
                }
                Err(e) => {
                    let mut stderr = io::stderr().lock();
                    let _ = writeln!(stderr, "Error: {}", e);
                    return ExitCode::from(1);
                }
            }
        }
        if n_read != 32 {
            let mut stderr = io::stderr().lock();
            let _ = writeln!(stderr, "Error: expected 32 key bytes from stdin, found {}", n_read);
            return ExitCode::from(1);
        }
        HashKey::Keyed(buf)
    } else if let Some(ctx) = &args.derive_key {
        HashKey::DeriveKey(ctx.clone())
    } else {
        HashKey::Regular
    };

    if args.check {
        do_check(&args, &key)
    } else {
        do_hash(&args, &key)
    }
}
